"""Validation for a Peg's published skills.

A Peg's ``skills`` block — named, versioned instruction packs a person may
select for a turn — is authored in ``workpeg.json`` beside ``search``,
``actions`` and ``renderers``::

    {
      "skills": [{
        "name": "verify-after-write",
        "version": "1.2.0",
        "instructions": "After any write action, read the row back and "
                        "confirm the value that landed. Never report success "
                        "from the request alone.",
        "tools": ["create_invoice", "void_invoice"],
        "title": "Verify after write"
      }]
    }

A skill is addressed ``namespace:name`` — the namespace comes from the Peg,
so it is NOT written inside a skill entry (a ``namespace`` key is therefore
an unknown key and refused). The platform denormalises it from the peg's own
name when it ingests the row, so this section stays identical for every
business that installs the Peg.

**A skill IS instructions**, which is a different and more dangerous thing
than a description or a label. It is third-party text bound for the SYSTEM
PROMPT — the most privileged position a request has. Everything here is
UNTRUSTED, and the caps below are the AUTHOR'S EARLY WARNING, not the
security boundary: the platform re-validates the bytes actually at the CDN
URL on ingest, strips controls and re-checks the byte cap at write, and
re-checks it AGAIN when it composes the block into a prompt. A skill that
only found out on the server has already shipped. Learning it at build time
is the entire point.

Two caps here are deliberately NOT copied from the nearest sibling, because
copying would silently break a legal skill:

* **``instructions`` is capped in UTF-8 BYTES, not characters.** The platform
  counts bytes (``skill_models.instruction_weight``); a code-point cap is
  roughly four times looser than it reads for non-Latin text, so a
  Cyrillic/CJK instruction pack that passed a naive character cap here would
  be refused on ingest — the exact broken promise a build-time check exists
  to prevent. :func:`_instructions` counts bytes.
* **a skill ``name`` allows a hyphen** (the seed skill is literally
  ``verify-after-write``). ``actions`` and ``renderers`` forbid the hyphen
  because their names are a *provider tool name* and half of a render
  address; a skill name is neither. :data:`_NAME_RE` here is byte-identical
  to the platform's ``skill_models._NAME_RE`` so the two can be pinned equal.
"""
import re

#: Keys a skill may declare. Anything else is refused rather than ignored —
#: a typo in an optional key is otherwise a silent no-op, and ``namespace``
#: in particular is inherited from the Peg, never author-supplied.
KEYS = ("name", "version", "instructions", "tools", "title")
REQUIRED = ("name", "version", "instructions")

#: How many skills one Peg may publish. Unlike ``actions``, a skill is NOT
#: sent to the model on every turn — the platform composes exactly the ONE a
#: person selected, so a skill costs context only when chosen. This ceiling
#: is about the size of the manifest and the length of a future selector,
#: not a per-turn bill. The figure mirrors ``MAX_ACTIONS``; the platform's
#: ingestion holds a matching ``MAX_SKILLS_PER_PEG``.
#:
#: It is NOT the real ceiling on how much skill text one Peg can publish, and
#: nothing here could be: this cap times :data:`MAX_INSTRUCTIONS_BYTES` is
#: 240 KB, while the platform refuses to read a ``manifest.json`` over 64 KB
#: at all. A per-entry cap cannot bound a document, so the document is
#: measured where it is written — ``build._check_manifest_size``.
MAX_SKILLS = 24

#: Caps that must land exactly where the platform's columns and checks do, so
#: build-time and ingest-time never disagree. Each equals the constant of the
#: same meaning in the API's ``core.models.skill_models``.
MAX_NAME = 64                       # == skill_models.MAX_NAME
MAX_VERSION = 50                    # == Skill.version column width (MAX_VERSION)
MAX_TITLE = 80                      # == skill_models.MAX_TITLE
MAX_TOOLS = 24                      # == skill_models.MAX_TOOLS
MAX_TOOL_NAME = 100                 # == skill_models.MAX_TOOL_NAME
#: BYTES, not characters — see the module docstring and :func:`_instructions`.
MAX_INSTRUCTIONS_BYTES = 10_000     # == skill_models.MAX_INSTRUCTIONS_BYTES

#: A skill name. HYPHEN ALLOWED — this is not a provider tool name. The string
#: is byte-identical to ``skill_models._NAME_RE`` so a drift test can pin them.
_NAME_RE = re.compile(r"[a-z][a-z0-9_-]*\Z")
#: Opaque — never parsed, never ordered. == ``skill_models._VERSION_RE``.
_VERSION_RE = re.compile(r"[0-9A-Za-z][0-9A-Za-z.\-]*\Z")
#: C0/C1 controls except the tab and newline instructions may contain — and
#: LONE SURROGATES, which are in this class for a sharper reason than the
#: rest. A surrogate is not merely invisible: a string carrying one cannot be
#: encoded to UTF-8 at all, so it is not something the platform displays
#: oddly, it is something the platform cannot count, store or send without
#: raising. The build is the only place an author can be told, because by
#: ingest time the only visible symptom is that their skill never arrived.
_CONTROL_RE = re.compile(r"[\x00-\x08\x0b-\x1f\x7f-\x9f\ud800-\udfff]")


class SkillValidationError(ValueError):
    """A ``skills`` block the platform would refuse, or should."""


def _text(value, key, cap, where):
    """A short identity/label string: non-empty, no controls, char-capped.

    Serves ``name``, ``version`` and ``title`` — the fields whose cap is a
    code-point count. ``instructions`` cannot use this: its cap is bytes.
    """
    if not isinstance(value, str) or not value.strip():
        raise SkillValidationError(
            f"{where}: {key} must be a non-empty string")
    if _CONTROL_RE.search(value):
        raise SkillValidationError(
            f"{where}: {key} contains control characters. They are invisible "
            f"on screen and can be used to disguise text sent to the model.")
    if len(value) > cap:
        raise SkillValidationError(
            f"{where}: {key} is {len(value)} characters; the limit is {cap}.")
    return value


def _instructions(value, where):
    """The instruction pack. The one field whose cap is UTF-8 BYTES.

    Refused, not stripped, on controls: a silent strip is the "you shipped
    something you didn't write" failure this file exists to prevent, and
    refusing does not create a burned-version divergence (the author cleans
    it, the clean bytes reach the manifest, and the platform's own strip is
    then a no-op). The byte cap is the same wall the server enforces on
    ingest and again at composition, felt here at build time.
    """
    if not isinstance(value, str) or not value.strip():
        raise SkillValidationError(
            f"{where}: instructions must be a non-empty string")
    if _CONTROL_RE.search(value):
        raise SkillValidationError(
            f"{where}: instructions contain control characters. They are "
            f"invisible on screen and can disguise text sent to the model.")
    size = len(value.encode("utf-8"))
    if size > MAX_INSTRUCTIONS_BYTES:
        raise SkillValidationError(
            f"{where}: instructions are {size} bytes; the limit is "
            f"{MAX_INSTRUCTIONS_BYTES}. The platform counts UTF-8 BYTES, not "
            f"characters, and refuses an over-cap row on ingest — this is "
            f"the same wall, felt at build time.")
    return value


def _validate_tools(tools, where):
    """The declared tool names. DECLARED, GRANTS NOTHING.

    Shape only — a flat list of non-empty strings — exactly as the platform
    shape-checks the column. Nothing reads it: a skill is guidance, not a
    capability, and declaring a tool name here confers no authority to call
    it. It exists so a future capability design can resolve these names
    without a migration; that design is the one that must re-argue the whole
    authority ceiling.

    "Shape only" still has to mean the BYTES, and this is the one field where
    forgetting that is expensive. Every other string in a skill is either
    grammar-locked (``name``, ``version``) or checked for controls
    (``instructions``, ``title``); ``tools`` is neither, and it is the only
    one the platform stores in a JSON column — where a NUL is not stored
    untidily but REFUSED, by the database driver, as an error a server-side
    caller has no reason to be catching. So it is refused here too, and
    refused rather than stripped: a tool name is a token, and a repaired
    token is a different token. Being told at build is the entire point of
    this file, and this was the single byte it had nothing to say about.
    """
    if not isinstance(tools, list) or len(tools) > MAX_TOOLS:
        raise SkillValidationError(
            f"{where}: tools must be a list of at most {MAX_TOOLS} tool "
            f"names. It DECLARES names and grants nothing — a skill adds "
            f"guidance, never a capability.")
    for entry in tools:
        if not isinstance(entry, str) or not entry or len(entry) > MAX_TOOL_NAME:
            raise SkillValidationError(
                f"{where}: each declared tool is a non-empty string of at "
                f"most {MAX_TOOL_NAME} characters")
        if _CONTROL_RE.search(entry):
            raise SkillValidationError(
                f"{where}: a declared tool name contains a control "
                f"character. They are invisible on screen, and the platform "
                f"stores this list as JSON — a NUL is refused outright "
                f"rather than stored, so the skill would never arrive.")
    return list(tools)


def validate_skill(skill, where="skill"):
    """One skill, returned with its declared keys only."""
    if not isinstance(skill, dict):
        raise SkillValidationError(f"{where}: each skill must be an object")

    unknown = sorted(set(skill) - set(KEYS))
    if unknown:
        raise SkillValidationError(
            f"{where}: unexpected key(s) {', '.join(unknown)} — only "
            f"{', '.join(KEYS)} are read. A key the platform does not know "
            f"is silently ignored, so it is refused here instead. (A "
            f"skill's namespace is inherited from the Peg, never declared.)")
    missing = [key for key in REQUIRED if key not in skill]
    if missing:
        raise SkillValidationError(
            f"{where}: missing required key(s) {', '.join(missing)}")

    name = _text(skill["name"], "name", MAX_NAME, where)
    if not _NAME_RE.fullmatch(name):
        raise SkillValidationError(
            f"{where}: name {name!r} must be lowercase — a letter, then "
            f"letters, digits, '_' or '-'.")

    version = _text(skill["version"], "version", MAX_VERSION, where)
    if not _VERSION_RE.fullmatch(version):
        raise SkillValidationError(
            f"{where}: version {version!r} must be letters, digits, dots and "
            f"hyphens. It is opaque — a version, once published, is burned, "
            f"and never parsed or ordered.")

    out = {
        "name": name,
        "version": version,
        "instructions": _instructions(skill["instructions"], where),
    }
    if "tools" in skill:
        out["tools"] = _validate_tools(skill["tools"], where)
    if "title" in skill:
        out["title"] = _text(skill["title"], "title", MAX_TITLE, where)
    return out


def validate(block) -> list:
    """Validate a ``skills`` block and return the declared skills."""
    if not isinstance(block, list):
        raise SkillValidationError(
            "the 'skills' block in workpeg.json must be a list of skills")
    if len(block) > MAX_SKILLS:
        raise SkillValidationError(
            f"{len(block)} skills declared; the limit is {MAX_SKILLS}.")

    out, seen = [], set()
    for index, entry in enumerate(block):
        validated = validate_skill(entry, where=f"skills[{index}]")
        if validated["name"] in seen:
            raise SkillValidationError(
                f"skills[{index}]: {validated['name']!r} is declared twice. "
                f"A manifest is the Peg's CURRENT set of skills — one entry "
                f"per name; a new version is a new build, not a second entry "
                f"in the same file.")
        seen.add(validated["name"])
        out.append(validated)
    return out
